// ELEMENTS:
// 1. Navy liso com o filete vermelho no topo
// 2. Ícone de casa em traço fino que se desenha
// 3. Eyebrow (traço vermelho + etiqueta), pergunta palavra a palavra (Light, **palavras** em Heavy)
// 4. Sub + mosaicos numerados (steps) a aparecer em sequência
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const LINE = "rgba(255,255,255,0.45)";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.08, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

// "Quem tem **isenção** de **IMI**?" → words, the starred ones heavy.
const words = (text: string): { w: string; bold: boolean }[] => {
  const out: { w: string; bold: boolean }[] = [];
  text.split(/(\*\*[^*]+\*\*)/).forEach((part) => {
    const bold = part.startsWith("**");
    part.replace(/\*\*/g, "").split(/\s+/).filter(Boolean).forEach((w) => {
      // Bare punctuation ("?" after **IMI**) sticks to the word before it, not floating on its own.
      if (out.length && !/[\p{L}\p{N}]/u.test(w)) out[out.length - 1].w += w;
      else out.push({ w, bold });
    });
  });
  return out;
};

const TituloPergunta: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const steps = Math.max(0, Math.min(8, Number(p.steps ?? 0) || 0));
  const list = words(String(anim.text ?? ""));

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number, dist = 26): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * dist * u}px)` };
  };
  const draw = show(0, 1.4);
  const wordsEnd = 0.45 + list.length * 0.12;

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", textAlign: "center", padding: `0 ${90 * u}px`, gap: 40 * u }}>
        <svg width={190 * u} height={190 * u} viewBox="0 0 120 120" style={{ overflow: "visible" }}>
          <path d="M14 60 L60 20 L106 60 M26 50 V104 H94 V50 M50 104 V76 H70 V104" fill="none" stroke={WHITE} strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - draw} />
          <circle cx={92} cy={30} r={5} fill={RED} opacity={show(1.2, 0.4)} />
        </svg>
        {eyebrow ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 30 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST, ...rise(0.25) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {eyebrow}
          </div>
        ) : null}
        <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: 26 * u, rowGap: 6 * u, maxWidth: 920 * u }}>
          {list.map((x, i) => (
            <span key={i} style={{ fontFamily: FONTS.display, fontWeight: x.bold ? 800 : 300, fontSize: 118 * u, lineHeight: 1.05, color: WHITE, display: "inline-block", ...rise(0.45 + i * 0.12, 40) }}>
              {x.w}
            </span>
          ))}
        </div>
        <div style={{ width: show(wordsEnd, 0.8) * 120 * u, height: 3 * u, background: RED }} />
        {sub ? (
          <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 52 * u, color: MIST, ...rise(wordsEnd + 0.2) }}>{sub}</div>
        ) : null}
        {steps > 0 ? (
          <div style={{ display: "flex", gap: 22 * u }}>
            {Array.from({ length: steps }, (_, i) => {
              const t = show(wordsEnd + 0.45 + i * 0.16, 0.5);
              return (
                <div key={i} style={{ width: 92 * u, height: 92 * u, border: `${2 * u}px solid ${LINE}`, borderRadius: 14 * u, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONTS.mono, fontSize: 40 * u, color: WHITE, opacity: t, transform: `scale(${0.7 + 0.3 * t})` }}>
                  {i + 1}
                </div>
              );
            })}
          </div>
        ) : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default TituloPergunta;
